def validate_search(args):
    if not isinstance(args,dict) or set(args)-{"query","limit"}:
        raise ValueError("Invalid fields")
    query, limit = args.get("query"), args.get("limit",3)
    if not isinstance(query,str) or not query.strip():
        raise ValueError("query must be nonblank")
    if type(limit) is not int or not 1 <= limit <= 10:
        raise ValueError("limit must be integer 1..10")
    return {"query":query.strip(),"limit":limit}

