def execute_call(raw):
    import json
    try:
        call = json.loads(raw)
        if not isinstance(call,dict) or set(call) != {"tool","args"} or call["tool"] != "add":
            raise ValueError("Invalid call")
        args = call["args"]
        if not isinstance(args,dict) or set(args) != {"a","b"} or any(type(v) not in (int,float) for v in args.values()):
            raise ValueError("Invalid args")
        return {"ok":True,"result":args["a"]+args["b"]}
    except (ValueError,TypeError):
        return {"ok":False,"error":"invalid_call"}

