exercise.solution:
def schedule(steps,max_steps):
    done, order = set(), []
    for _ in range(max(0,max_steps)):
        if len(done) == len(steps):
            return {"status":"done","order":order}
        ready = [s for s in steps if s["id"] not in done and all(d in done for d in s["depends_on"])]
        if not ready:
            return {"status":"blocked","order":order}
        step = ready[0]
        done.add(step["id"])
        order.append(step["id"])
    return {"status":"done" if len(done)==len(steps) else "budget_exhausted","order":order}

