exercise.solution:
def repeated_action(actions,limit):
    import json
    if limit <= 0:
        raise ValueError("limit must be positive")
    counts = {}
    for action in actions:
        key = json.dumps(action,sort_keys=True,separators=(",",":"))
        counts[key] = counts.get(key,0)+1
        if counts[key] >= limit:
            return True
    return False

