def search_docs(query,docs):
    terms = set(query.lower().split())
    return [doc["id"] for doc in docs if terms & set(doc["text"].lower().split())]

def agent_step(state,docs):
    phase = state.get("phase","search")
    if phase == "search":
        hits = search_docs(state["query"],docs)
        return {**state,"phase":"read" if hits else "done","selected":hits[0] if hits else None,"answer":None if hits else "No evidence.","trace":[*state.get("trace",[]),"search"]}
    if phase == "read":
        doc = next((d for d in docs if d["id"] == state["selected"]),None)
