def run_agent(query,docs,max_steps=4):
    state = {"query":query,"phase":"search","trace":[],"answer":None}
    for _ in range(max(0,max_steps)):
        if state["phase"] == "done":
            break
        state = agent_step(state,docs)
    return {"mode":"simulated","status":"done" if state["phase"]=="done" else "budget_exhausted","answer":state["answer"],"trace":state["trace"]}
